/**
 * Copy the sample dataset into public/ so the deployed frontend can fetch it.
 *
 * The CSV lives in ../data as the single source of truth, generated by
 * scripts/generate_sample_data.py. Committing a second copy under public/
 * would let the two drift; copying at build time cannot.
 *
 * Runs on `npm run dev` and `npm run build`, so a fresh clone works either way.
 */

import { copyFileSync, existsSync, mkdirSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const source = resolve(here, "../../data/sample_orders.csv");
const target = resolve(here, "../public/sample_orders.csv");

if (!existsSync(source)) {
  console.error(
    `[copy-sample-data] ${source} is missing.\n` +
      "Run: python scripts/generate_sample_data.py",
  );
  process.exit(1);
}

mkdirSync(dirname(target), { recursive: true });
copyFileSync(source, target);
console.log("[copy-sample-data] public/sample_orders.csv written");
